# 11/25 대진고2 요약문 끝판왕 1·2·4~10 어휘 끝판왕화 — 선생님: "대진고는 하나도 안 풀었어, 고2인 만큼 난이도 확실히"
# boss6_data.py에서 exec(boss6_s3 뒤). 고정 규칙: 정답 = 다의어의 숨은 뜻·고급 어휘('이런 뜻도 있다고?'), 오답 = 철자·소리 함정·흔한 뜻 함정·그럴듯한 반대말, 정답의 동의어는 오답에 넣지 않음
# 서술형(wr)·근거(gr)·난이도(하/중/상)·정답 위치(rot)는 그대로, 선택형 문장·선택지·해석·해설만 새로
from boss2_data import mc
import re
HD = {}   # 낱말 뜻 (→ HMEAN3에 합침)
def _tr(o, why):
    a, b = o[0]
    t = '함정 ▶ %s = %s, %s = %s.' % (a, HD[a], b, HD[b])
    for w in dict.fromkeys(x for p in o[1:] for x in p if x not in (a, b)):
        y = re.sub(r'^\([^)]*\)', '', why.get(w, ' 근거와 달라요.'))
        t += ' ① %s(%s)%s%s' % (w, HD[w], '' if re.match(r'[은는이가을를도와과의로]', y) else ' ', y.strip() if not re.match(r'[은는이가을를도와과의로]', y) else y)
    return t
def X(lv, s, o, ko, why, gm=''):
    assert o[1][0] == o[0][0] and o[2][1] == o[0][1] and len(set(o)) == 5, o
    for w in why: assert any(w in p for p in o[1:]), (w, o)
    return (lv, s, o, ko, why, gm)
def apply(sid, items):
    S = next(S for S in SETS if S['id'] == sid)
    slots = [i for i, it in enumerate(S['items']) if it['lv'] != '서술']
    assert len(slots) == len(items) == 18, (sid, len(items))
    for i, (lv, s, o, ko, why, gm) in zip(slots, items):
        for p in o:
            for w in p: assert w in HD, (sid, w)
        assert s.count('{A}') == 1 and s.count('{B}') == 1, s
        tr = _tr(o, why)
        old = S['items'][i]
        assert old['lv'] == lv, (sid, i, old['lv'], lv)
        S['items'][i] = mc(lv, s, o, old['at'], ko, old['gr'], tr, gm=gm or old.get('gm', ''))
    S['hard'] = True

